const FRAME = {
	aspect: 9 / 10,
	layoutAspect: 2 / 3,
	zoom: .66
};

//#endregion
//#region ../../.codex/worktrees/e8b9/3d-svg-workshop/src/animation/frame-pacing.js
function createFramePacer(fps = 60) {
	const interval = 1e3 / fps;
	let next = null;
	return {
		reset() {
			next = null;
		},
		ready(now) {
			if (next !== null && now + .5 < next) return false;
			if (next === null || now - next > interval * 2) next = now;
			next += interval;
			return true;
		}
	};
}

